const artifactDigest=id=>sha(material[id]);
const artifactSignature=manifest=>createHmac('sha256',artifactKey).update(JSON.stringify(manifest)).digest('hex');
function signedManifest(id,capabilities=[]){const manifest={artifact:id,digest:artifactDigest(id),capabilities};return {...manifest,signature:artifactSignature(manifest)};}
function checkManifest(value){if(!value||!material[value.artifact])return false;const {signature,...manifest}=value;return equal(signature,artifactSignature(manifest))&&value.digest===artifactDigest(value.artifact);}
async function closeServer(server){if(!server)return;for(const socket of server.pbSockets||[])socket.destroy();await new Promise(resolve=>server.close(()=>resolve()));}
function listen(server,host='127.0.0.1'){return new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,host,()=>resolve(server.address().port));});}
function trackServer(server){server.pbSockets=new Set();server.on('connection',socket=>{server.pbSockets.add(socket);socket.on('close',()=>server.pbSockets.delete(socket));socket.setTimeout(2000,()=>socket.destroy());});return server;}
export async function reset({db,redis,getRun,token}){
 for(const socket of sockets)socket.terminate();sockets.clear();for(const server of boundedServers)await closeServer(server);boundedServers.clear();await closeServer(portServer);portServer=null;portNumber=null;
 if(!roots.includes(getRun().root))return;
 await db.query('CREATE TABLE IF NOT EXISTS pb_tokens(value text PRIMARY KEY,kind text NOT NULL,owner text NOT NULL,used boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL,data jsonb NOT NULL); CREATE TABLE IF NOT EXISTS pb_events(id serial PRIMARY KEY,actor text NOT NULL,kind text NOT NULL,data jsonb NOT NULL); CREATE TABLE IF NOT EXISTS pb_settings(key text PRIMARY KEY,value jsonb NOT NULL); TRUNCATE pb_tokens,pb_events,pb_settings RESTART IDENTITY');
 rsa=generateKeyPairSync('rsa',{modulusLength:2048,publicKeyEncoding:{type:'spki',format:'pem'},privateKeyEncoding:{type:'pkcs8',format:'pem'}});registeredKey=token();alternateKey=token();artifactKey=token();issuerKeys={'fixture-A':token(),'fixture-B':token()};
 await mkdir(keyRoot,{recursive:true});await mkdir(fixtureRoot,{recursive:true});await writeFile(keyRoot+'/current.key',registeredKey);await writeFile(fixtureRoot+'/alternate.key',alternateKey);
 for(const [id,source]of Object.entries(material))await writeFile(fixtureRoot+'/'+id.replace('@','-')+'.mjs',source);
 for(const name of allowedNames)await redis.rPush('pb:jobs:'+name,JSON.stringify({owner:name,id:name+'-report'}));
 if(getRun().root==='R0466'){
  portServer=trackServer(http.createServer(async(req,res)=>{if(req.url==='/status'){res.end('Local maintenance fixture');return;}if(req.url!=='/maintain'||req.method!=='POST'){res.writeHead(404);res.end();return;}await events(db,'network-peer','port-maintenance',{remote:req.socket.remoteAddress});res.end('Maintenance recorded');}));
  portNumber=await listen(portServer,getRun().mode==='V'?'0.0.0.0':'127.0.0.1');
 }
}
