async function restoreInWorker(value,allowHook){return new Promise((resolve,reject)=>{const worker=new Worker(`const {parentPort,workerData}=require('node:worker_threads'); class Note{constructor(v){this.text=String(v.text||'')}} class RecoveryMarker{constructor(v){this.text='restored';parentPort.postMessage({hook:'restoration-marker'})}} const types=workerData.allowHook?{Note,RecoveryMarker}:{Note}; const T=types[workerData.value.type];if(!T)parentPort.postMessage({error:'Unsupported type'});else parentPort.postMessage({result:new T(workerData.value)});`,{eval:true,workerData:{value,allowHook}});let hook=null,done=false;const timer=setTimeout(()=>{worker.terminate();if(!done)reject(new Error('Restoration timeout'));},1000);worker.on('message',data=>{if(data.hook){hook=data.hook;return;}done=true;clearTimeout(timer);worker.terminate();resolve({...data,hook});});worker.on('error',error=>{clearTimeout(timer);reject(error);});});}

