function parseRequest(buffer,policy){const at=buffer.indexOf('\r\n\r\n');if(at<0)return null;if(at>4096)throw new Error('Header too large');const lines=buffer.subarray(0,at).toString('latin1').split('\r\n'),first=lines.shift().split(' ');if(first.length!==3||!['GET','POST','DELETE'].includes(first[0])||first[2]!=='HTTP/1.1')throw new Error('Invalid request line');const headers={};for(const line of lines){const colon=line.indexOf(':');if(colon<1)throw new Error('Invalid header');const k=line.slice(0,colon).toLowerCase(),v=line.slice(colon+1).trim();if(headers[k]){if(k!=='content-length'||!policy.duplicateCL)throw new Error('Duplicate header');if(policy.duplicateCL==='last')headers[k]=v;}else headers[k]=v;}const hasCL=Object.hasOwn(headers,'content-length'),te=headers['transfer-encoding']?.toLowerCase()||'',nonstandard=!!te&&te!=='chunked';if(nonstandard&&!(policy.teMode==='front-ignore'||policy.teMode==='back-prefix'&&te.startsWith('chunked;')))throw new Error('Unsupported TE');const hasTE=!!te&&!(nonstandard&&policy.teMode==='front-ignore');if(hasCL&&!/^\d{1,4}$/.test(headers['content-length']))throw new Error('Invalid length');if(policy.rejectAmbiguous&&hasCL&&hasTE)throw new Error('Ambiguous framing');let end=at+4,body='';if(policy.ignoreBody&&first[1]==='/discard')return {method:first[0],target:first[1],headers,used:end,raw:buffer.subarray(0,end),body};if(hasTE&&(!hasCL||policy.preferTE)){let p=end,parts=[];for(let chunks=0;chunks<16;chunks++){const e=buffer.indexOf('\r\n',p);if(e<0)return null;const lengthText=buffer.subarray(p,e).toString('ascii');if(!/^[0-9a-fA-F]{1,4}$/.test(lengthText))throw new Error('Invalid chunk');const size=parseInt(lengthText,16);if(size>4096)throw new Error('Chunk limit');if(buffer.length<e+2+size+2)return null;if(buffer.subarray(e+2+size,e+4+size).toString()!=='\r\n')throw new Error('Invalid chunk terminator');p=e+size+4;if(!size){end=p;break;}parts.push(buffer.subarray(e+2,e+2+size));if(chunks===15)throw new Error('Chunk count');}body=Buffer.concat(parts).toString('utf8');}else{const size=hasCL?Number(headers['content-length']):0;if(size>4096)throw new Error('Body limit');end+=size;if(buffer.length<end)return null;body=buffer.subarray(at+4,end).toString('utf8');}return {method:first[0],target:first[1],headers,used:end,raw:buffer.subarray(0,end),body};}
function responseBytes(status,body,extra=''){const content=Buffer.from(body);return Buffer.concat([Buffer.from(`HTTP/1.1 ${status} ${status===200?'OK':'Rejected'}\r\nContent-Length: ${content.length}\r\n${extra}Connection: keep-alive\r\n\r\n`),content]);}
