 const backend=internal=>trackServer(net.createServer(socket=>{let buffer=Buffer.alloc(0),pending=Promise.resolve();socket.on('data',data=>{buffer=Buffer.concat([buffer,data]);if(buffer.length>8192){socket.destroy();return;}try{for(;;){const req=parseRequest(buffer,{preferTE:root==='R0351',ignoreBody:root==='R0356'&&unsafe,duplicateCL:getRun().variant==='B0352'&&unsafe?'last':undefined,teMode:getRun().variant==='B0353'&&unsafe?'back-prefix':undefined});if(!req)break;buffer=buffer.subarray(req.used);if(++count>12){socket.destroy();break;}pending=pending.then(async()=>{let target=req.target;if(/^http:\/\//.test(target))target=new URL(target).pathname;if(root==='R0365'&&unsafe&&req.headers['x-original-url'])target=req.headers['x-original-url'];if(root==='R0358')target=path.posix.normalize(target);let method=root==='R0357'&&req.headers['x-http-method-override']?req.headers['x-http-method-override'].toUpperCase():req.method;trace.push({stage:'backend',method,target,internal,bodyBytes:Buffer.byteLength(req.body)});await events(db,actor,'wire-request',{method,target,internal});let body='Public fixture response',extra='';if(internal||target==='/admin'){body=getRun().canary;await events(db,actor,'wire-admin',{method,target,internal});}if(root==='R0357'&&target==='/record'&&method==='DELETE'){await events(db,actor,'wire-delete');body='Record deleted';}if(root==='R0362'&&target.startsWith('/note?')){const value=new URL(target,'http://public.lab').searchParams.get('value')||'';if(!unsafe&&/[\x00-\x1f\x7f]/.test(value)){socket.write(responseBytes(400,'Invalid header value'));return;}extra='X-Note: '+value+'\r\n';}socket.write(responseBytes(200,body,extra));}).catch(()=>socket.destroy());}}catch{socket.write(responseBytes(400,'Invalid HTTP framing'));}});}));
 const publicServer=backend(false),internalServer=backend(true);servers.push(publicServer,internalServer);const publicPort=await listen(publicServer),internalPort=await listen(internalServer);
 const front=trackServer(net.createServer(socket=>{let buffer=Buffer.alloc(0),downstream=null,chosen=null;socket.on('data',data=>{buffer=Buffer.concat([buffer,data]);if(buffer.length>8192){socket.destroy();return;}try{for(;;){const req=parseRequest(buffer,{preferTE:false,rejectAmbiguous:!unsafe,duplicateCL:getRun().variant==='B0352'&&unsafe?'first':undefined,teMode:getRun().variant==='B0353'&&unsafe?'front-ignore':undefined});if(!req)break;buffer=buffer.subarray(req.used);let authority=req.headers.host||'',target=req.target,normalized=path.posix.normalize(target),effectiveMethod=req.headers['x-http-method-override']||req.method;let absolute=null;if(/^http:\/\//.test(target)){absolute=new URL(target);normalized=absolute.pathname;}let denied=target==='/admin'||(!unsafe&&root==='R0358'&&normalized==='/admin')||((root==='R0357')&&(unsafe?req.method:effectiveMethod)==='DELETE'&&actor!=='admin');if(!['public.lab','internal.lab'].includes(authority))denied=true;if(!unsafe&&authority!=='public.lab')denied=true;if(!unsafe&&absolute&&absolute.host!==authority)denied=true;if(denied){socket.write(responseBytes(403,'Forbidden route'));continue;}let internal=(root==='R0364'&&unsafe&&authority==='internal.lab')||(root==='R0366'&&unsafe&&absolute?.hostname==='internal.lab');const dest=internal?internalPort:publicPort;if(chosen!==null&&chosen!==dest){socket.write(responseBytes(400,'Upstream change forbidden'));continue;}chosen=dest;trace.push({stage:'frontend',method:req.method,target,bodyBytes:Buffer.byteLength(req.body),internal});let forwarded=req.raw;if(!unsafe&&root==='R0365')forwarded=Buffer.from(req.raw.toString('latin1').replace(/^x-original-url:[^\r]*\r\n/gim,''),'latin1');if(!downstream){downstream=net.connect({host:'127.0.0.1',port:dest});downstream.on('data',chunk=>socket.write(chunk));downstream.on('error',()=>socket.destroy());socket.on('close',()=>downstream.destroy());}downstream.write(forwarded);}}catch{socket.write(responseBytes(400,'Invalid HTTP framing'));}});}))